<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\User; use App\Models\Transaction; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash;
class TransferController extends Controller{ public function store(Request $request){$data=$request->validate(['receiver_id'=>'required|exists:users,id','amount'=>'required|numeric|min:1000','pin'=>'required']);$sender=$request->user(); if($sender->id==(int)$data['receiver_id']) return response()->json(['status'=>false,'message'=>'Tidak bisa transfer ke diri sendiri'],422); if(!Hash::check($data['pin'],$sender->pin)) return response()->json(['status'=>false,'message'=>'PIN salah'],422); $ref='TR'.date('YmdHis').random_int(1000,9999); try{DB::transaction(function()use($sender,$data,$ref){$receiver=User::findOrFail($data['receiver_id']);$sw=$sender->wallet()->lockForUpdate()->firstOrCreate(['user_id'=>$sender->id],['balance'=>0]);$rw=$receiver->wallet()->lockForUpdate()->firstOrCreate(['user_id'=>$receiver->id],['balance'=>0]); if($sw->balance < $data['amount']) throw new \Exception('Saldo tidak cukup'); $sw->balance-=$data['amount'];$rw->balance+=$data['amount'];$sw->save();$rw->save();Transaction::create(['user_id'=>$sender->id,'type'=>'transfer_out','amount'=>$data['amount'],'status'=>'success','description'=>'Transfer keluar ke '.$receiver->name,'reference_no'=>$ref]);Transaction::create(['user_id'=>$receiver->id,'type'=>'transfer_in','amount'=>$data['amount'],'status'=>'success','description'=>'Transfer masuk dari '.$sender->name,'reference_no'=>$ref]);});return response()->json(['status'=>true,'message'=>'Transfer berhasil','reference_no'=>$ref]);}catch(\Exception $e){return response()->json(['status'=>false,'message'=>$e->getMessage()],422);}}}
